    for (tb in 0 until a[1]) {
        val tmp = a[3] - tb * a[5]
        if (tmp == a[0]) {
            println("YES")
            return
        }
    }
    for (ta in 0 until a[1]) {
        for (tb in 0 until a[1]) {
            val tmp = (a[2] - ta * a[4]) + (a[3] - tb * a[5])
            if (tmp == a[0]) {
                println("YES")
                return
            }
        }
    }
    println("NO")
}

